import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"moparticles/faq.md","filePath":"moparticles/faq.md","lastUpdated":1788317173000}'),o={name:"moparticles/faq.md"};function i(n,e,l,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="do-players-need-to-install-anything" tabindex="-1">Do players need to install anything? <a class="header-anchor" href="#do-players-need-to-install-anything" aria-label="Permalink to &quot;Do players need to install anything?&quot;">​</a></h2><p>Yes — the <strong>generated resource pack</strong>. It contains the item models and particle textures the animations are built from, and it&#39;s what makes the effects render. Distribute <code>plugins/MoParticles/generated/resourcepack.zip</code> to your players (download link, shared folder, or launcher). There is no client mod and no server-side dependency beyond Paper.</p><h2 id="which-minecraft-versions-are-supported" tabindex="-1">Which Minecraft versions are supported? <a class="header-anchor" href="#which-minecraft-versions-are-supported" aria-label="Permalink to &quot;Which Minecraft versions are supported?&quot;">​</a></h2><p>MoParticles is built against Paper <strong>1.21.11</strong> and requires <strong>Java 21</strong> on the server. Clients need a recent 1.21.x client for item-display models to render. If you hit an issue on a different build, <a href="https://github.com/Chest-Solutions/MoParticles/issues" target="_blank" rel="noreferrer">open an issue</a> — version support is an active goal.</p><h2 id="is-it-laggy" tabindex="-1">Is it laggy? <a class="header-anchor" href="#is-it-laggy" aria-label="Permalink to &quot;Is it laggy?&quot;">​</a></h2><p>MoParticles is designed to be cheap: the MoLang simulation happens <strong>once</strong> when an effect is loaded (the &quot;baking&quot; step), and playback is a stream of vanilla item-display updates. The main cost at runtime scales with:</p><ul><li>the <strong>radius</strong> of the effect (more viewers → more updates),</li><li>the <strong>number of simultaneous animations</strong>,</li><li>how many particles per frame the effect produces.</li></ul><p>Keep radii reasonable for busy lobbies, and use <code>/moparticles stopall</code> when you&#39;re done.</p><h2 id="can-i-use-existing-snowstorm-effects" tabindex="-1">Can I use existing SnowStorm effects? <a class="header-anchor" href="#can-i-use-existing-snowstorm-effects" aria-label="Permalink to &quot;Can I use existing SnowStorm effects?&quot;">​</a></h2><p>That&#39;s the point. The three bundled effects are taken from <a href="https://github.com/SkyFabriK/snowstorm" target="_blank" rel="noreferrer">SnowStorm</a>. Drop any compatible <code>particle_effect</code> JSON into <code>plugins/MoParticles/particles/</code> and run <code>/moparticles reload</code>.</p><h2 id="why-do-i-see-invisible-particles-nothing-at-all" tabindex="-1">Why do I see invisible particles / nothing at all? <a class="header-anchor" href="#why-do-i-see-invisible-particles-nothing-at-all" aria-label="Permalink to &quot;Why do I see invisible particles / nothing at all?&quot;">​</a></h2><p>In 90% of cases the viewers just don&#39;t have the resource pack. Check:</p><ol><li>The pack exists at <code>plugins/MoParticles/generated/resourcepack.zip</code>.</li><li>Viewers have it enabled.</li><li>The texture you reference actually exists (bundled: <code>circle.png</code>, <code>cube.png</code>).</li></ol><h2 id="can-i-edit-the-bundled-effects" tabindex="-1">Can I edit the bundled effects? <a class="header-anchor" href="#can-i-edit-the-bundled-effects" aria-label="Permalink to &quot;Can I edit the bundled effects?&quot;">​</a></h2><p>Yes. The bundled <code>.json</code> files are copied into <code>plugins/MoParticles/particles/</code> on first boot — edit them there (don&#39;t edit the jar), then <code>/moparticles reload</code>.</p><h2 id="is-moparticles-free-will-it-stay-free" tabindex="-1">Is MoParticles free? Will it stay free? <a class="header-anchor" href="#is-moparticles-free-will-it-stay-free" aria-label="Permalink to &quot;Is MoParticles free? Will it stay free?&quot;">​</a></h2><p>Yes. Chest Solutions projects are free and open source — the source is on <a href="https://github.com/Chest-Solutions/MoParticles" target="_blank" rel="noreferrer">GitHub</a> and contributions are welcome.</p><h2 id="where-do-i-report-bugs-or-request-features" tabindex="-1">Where do I report bugs or request features? <a class="header-anchor" href="#where-do-i-report-bugs-or-request-features" aria-label="Permalink to &quot;Where do I report bugs or request features?&quot;">​</a></h2><p>The <a href="https://github.com/Chest-Solutions/MoParticles/issues" target="_blank" rel="noreferrer">MoParticles issues page</a>, or the <a href="https://discord.gg/MsWqevupwh" target="_blank" rel="noreferrer">community Discord</a>.</p>',20)])])}const f=t(o,[["render",i]]);export{u as __pageData,f as default};
